CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, source_id TEXT, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, role TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true, offboarded BOOLEAN NOT NULL DEFAULT false, must_change_password BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS credentials (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, hash TEXT NOT NULL, salt TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, last_seen BIGINT NOT NULL, ip TEXT);
CREATE TABLE IF NOT EXISTS login_attempts (bucket TEXT PRIMARY KEY, n INTEGER NOT NULL, expires_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS login_attempts_expires ON login_attempts(expires_at);
CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, source_tenant TEXT NOT NULL DEFAULT 'altus', name TEXT NOT NULL, first_name TEXT, last_name TEXT, email TEXT, phone TEXT, alternate_phone TEXT, company TEXT, designation TEXT, city TEXT, state TEXT, pincode TEXT, area TEXT, location TEXT, lead_no TEXT, external_id TEXT, source_system TEXT, lead_source TEXT, lead_source_secondary TEXT, lead_type TEXT, lead_status TEXT, stage TEXT, pipeline TEXT, priority TEXT, permission TEXT, pso_date DATE, is_pre_ps_done BOOLEAN, owner_user_id TEXT REFERENCES users(id), team TEXT, next_follow_up_at TIMESTAMPTZ, last_call_at TIMESTAMPTZ, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ, custom_values JSONB NOT NULL DEFAULT '{}'::jsonb, legacy_finance JSONB NOT NULL DEFAULT '{}'::jsonb, source_checksum TEXT, import_run_id TEXT);
CREATE TABLE IF NOT EXISTS lead_calls (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, lead_id TEXT REFERENCES leads(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id), happened_at TIMESTAMPTZ, note TEXT, resolution TEXT, custom_values JSONB NOT NULL DEFAULT '{}'::jsonb, source_checksum TEXT, import_run_id TEXT);
CREATE TABLE IF NOT EXISTS lead_followups (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, lead_id TEXT REFERENCES leads(id) ON DELETE CASCADE, assigned_to TEXT REFERENCES users(id), due_at TIMESTAMPTZ, status TEXT, note TEXT, completed_at TIMESTAMPTZ, custom_values JSONB NOT NULL DEFAULT '{}'::jsonb, source_checksum TEXT, import_run_id TEXT);
CREATE TABLE IF NOT EXISTS lead_history (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, lead_id TEXT REFERENCES leads(id) ON DELETE CASCADE, occurred_at TIMESTAMPTZ, actor_id TEXT, action TEXT, entity TEXT, entity_id TEXT, field TEXT, from_value TEXT, to_value TEXT, note TEXT, custom_values JSONB NOT NULL DEFAULT '{}'::jsonb, source_checksum TEXT, import_run_id TEXT);
CREATE TABLE IF NOT EXISTS lead_messages (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, lead_id TEXT REFERENCES leads(id) ON DELETE CASCADE, sent_at TIMESTAMPTZ, channel TEXT, status TEXT, sender TEXT, body TEXT, custom_values JSONB NOT NULL DEFAULT '{}'::jsonb, source_checksum TEXT, import_run_id TEXT);
CREATE INDEX IF NOT EXISTS leads_stage_idx ON leads(stage);
CREATE INDEX IF NOT EXISTS leads_owner_idx ON leads(owner_user_id);
CREATE INDEX IF NOT EXISTS lead_calls_lead_idx ON lead_calls(lead_id,happened_at DESC);
CREATE INDEX IF NOT EXISTS lead_followups_lead_idx ON lead_followups(lead_id,due_at);
ALTER TABLE users ADD COLUMN IF NOT EXISTS must_change_password BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE users ADD COLUMN IF NOT EXISTS source_id TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS users_source_id_idx ON users(source_id) WHERE source_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS import_runs (id TEXT PRIMARY KEY, source TEXT NOT NULL, mode TEXT NOT NULL, checksum TEXT, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, status TEXT NOT NULL, report JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS template_categories (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, name TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true, source_checksum TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_templates (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, category_id TEXT REFERENCES template_categories(id), category TEXT, name TEXT NOT NULL, channel TEXT, subject TEXT, body TEXT, media_type TEXT, media_url TEXT, language TEXT, sequence INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT true, version INTEGER NOT NULL DEFAULT 1, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assignment_rules (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, name TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 0, enabled BOOLEAN NOT NULL DEFAULT true, rule JSONB NOT NULL DEFAULT '{}'::jsonb, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_targets (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, user_id TEXT REFERENCES users(id), target_date DATE, weekday INTEGER, non_keynote_target INTEGER NOT NULL DEFAULT 0, keynote_target INTEGER NOT NULL DEFAULT 0, total_target INTEGER NOT NULL DEFAULT 0, week_override INTEGER, quarter_override INTEGER, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), actor_user_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, field TEXT, old_value TEXT, new_value TEXT, ip TEXT);
CREATE TABLE IF NOT EXISTS master_values (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, master_type TEXT NOT NULL, code TEXT, label TEXT NOT NULL, colour TEXT, sort_order INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT true, value JSONB NOT NULL DEFAULT '{}'::jsonb, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspace_settings (setting_key TEXT PRIMARY KEY, value JSONB NOT NULL DEFAULT '{}'::jsonb, active BOOLEAN NOT NULL DEFAULT true, updated_by TEXT REFERENCES users(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS integration_catalog (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, name TEXT NOT NULL, provider TEXT, enabled BOOLEAN NOT NULL DEFAULT false, status TEXT, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), serial TEXT, cell TEXT, products JSONB NOT NULL DEFAULT '[]'::jsonb, backup_user_id TEXT REFERENCES users(id), lead_transfer_allowed BOOLEAN NOT NULL DEFAULT false, colour TEXT, source_id TEXT UNIQUE, active BOOLEAN NOT NULL DEFAULT true, offboarded_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS lead_products (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, lead_id TEXT NOT NULL, product_code TEXT NOT NULL, stage TEXT, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lead_product_events (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, lead_id TEXT NOT NULL, product_code TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, event_type TEXT NOT NULL, actor_user_id TEXT REFERENCES users(id), value JSONB NOT NULL DEFAULT '{}'::jsonb, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id));
CREATE TABLE IF NOT EXISTS registration_records (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, lead_id TEXT NOT NULL, paid BOOLEAN NOT NULL DEFAULT false, registered_at TIMESTAMPTZ, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id));
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, lead_id TEXT NOT NULL, amount NUMERIC, paid_at TIMESTAMPTZ, mode TEXT, note TEXT, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id));
CREATE TABLE IF NOT EXISTS video_library (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, name TEXT NOT NULL, media_url TEXT, active BOOLEAN NOT NULL DEFAULT true, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id));
CREATE TABLE IF NOT EXISTS message_log (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, lead_id TEXT, user_id TEXT REFERENCES users(id), channel TEXT NOT NULL, template_id TEXT, status TEXT, sent_at TIMESTAMPTZ, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id));
CREATE TABLE IF NOT EXISTS call_analytics_inputs (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, lead_id TEXT, user_id TEXT REFERENCES users(id), occurred_at TIMESTAMPTZ, status TEXT, duration_seconds INTEGER, resolution TEXT, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id));
CREATE TABLE IF NOT EXISTS marketing_sequences (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, name TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT false, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id));
CREATE TABLE IF NOT EXISTS marketing_sequence_steps (id TEXT PRIMARY KEY, source_id TEXT UNIQUE, sequence_id TEXT REFERENCES marketing_sequences(id), position INTEGER NOT NULL, action TEXT NOT NULL, configuration JSONB NOT NULL DEFAULT '{}'::jsonb, source_checksum TEXT, import_run_id TEXT REFERENCES import_runs(id));

CREATE INDEX IF NOT EXISTS audit_log_occurred_idx ON audit_log(occurred_at DESC);
CREATE INDEX IF NOT EXISTS audit_log_actor_idx ON audit_log(actor_user_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS audit_log_entity_idx ON audit_log(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS user_targets_user_date_idx ON user_targets(user_id, target_date);
CREATE INDEX IF NOT EXISTS master_values_type_idx ON master_values(master_type, active, sort_order);
CREATE INDEX IF NOT EXISTS lead_products_lead_idx ON lead_products(lead_id);
CREATE INDEX IF NOT EXISTS call_analytics_inputs_date_idx ON call_analytics_inputs(occurred_at DESC);
